macro_rules! Visit {
    () => {
        # [doc = " A trait to allow responding to a traversal designed to observe all entries in a tree, recursively while keeping track of"] # [doc = " paths if desired."] pub trait Visit { # [doc = " Sets the full path in the back of the queue so future calls to push and pop components affect it instead."] # [doc = ""] # [doc = " Note that the first call is made without an accompanying call to [`Self::push_back_tracked_path_component()`]"] # [doc = ""] # [doc = " This is used by the depth-first traversal of trees."] fn pop_back_tracked_path_and_set_current (& mut self) ; # [doc = " Sets the full path in front of the queue so future calls to push and pop components affect it instead."] # [doc = ""] # [doc = " This is used by the breadth-first traversal of trees."] fn pop_front_tracked_path_and_set_current (& mut self) ; # [doc = " Append a `component` to the end of a path, which may be empty."] # [doc = ""] # [doc = " If `component` is empty, store the current path."] fn push_back_tracked_path_component (& mut self , component : & BStr) ; # [doc = " Append a `component` to the end of a path, which may be empty."] fn push_path_component (& mut self , component : & BStr) ; # [doc = " Removes the last component from the path, which may leave it empty."] fn pop_path_component (& mut self) ; # [doc = " Observe a tree entry that is a tree and return an instruction whether to continue or not."] # [doc = " [`Action::Skip`][visit::Action::Skip] can be used to prevent traversing it, for example if it's known to the caller already."] # [doc = ""] # [doc = " The implementation may use the current path to learn where in the tree the change is located."] fn visit_tree (& mut self , entry : & gix_object :: tree :: EntryRef < '_ >) -> visit :: Action ; # [doc = " Observe a tree entry that is NO tree and return an instruction whether to continue or not."] # [doc = " [`Action::Skip`][visit::Action::Skip] has no effect here."] # [doc = ""] # [doc = " The implementation may use the current path to learn where in the tree the change is located."] fn visit_nontree (& mut self , entry : & gix_object :: tree :: EntryRef < '_ >) -> visit :: Action ; }
    };
}

Visit!()